use std::fs
use std::json
use std::process

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut names: Vec<string> = []
            let mut totals: Vec<float> = []
            for o in orders {
                let mut idx = -1
                let mut i = 0
                while i < names.len() as int {
                    if names[i] == o.customer { idx = i }
                    i += 1
                }
                if idx < 0 {
                    names.push(o.customer)
                    totals.push(0.0)
                    idx = names.len() as int - 1
                }
                for it in o.items {
                    totals[idx] = totals[idx] + (it.qty as float) * it.price
                }
            }
            let mut order: Vec<int> = []
            let mut k = 0
            while k < names.len() as int {
                order.push(k)
                k += 1
            }
            order.sort_by(|a, b| names[*a].cmp(&names[*b]))
            for j in order {
                println("${names[j]} ${totals[j]:.2}")
            }
        }
        Err(_) => {
            println("invalid input")
            process::exit(1)
        }
    }
}

